/**
 * GENERATED FILE PRODUCER — writes lib/geometry/__fixtures__/phase17-litres-pin.json: the litres of the 102
 * Phase 16 test boards (`phase16SurfaceBoards`, lib/geometry/__fixtures__/phase16-boards.ts) exactly as the app
 * reads them today, BEFORE the bottom contours of Phase 17 can take any foam off (D-20). Every one of those boards
 * has a flat bottom, so once the bottom is in the litres they must still read these figures to the last digit.
 * The output is generated and must never be hand-edited.
 *
 *   npx --no-install tsx --tsconfig ./tsconfig.json scripts/extract-phase17-litres-pin.ts
 *
 * run from the repository root. Like the Phase 16 pins, it is a record of the code as it stood, so it REFUSES to
 * run once `lib/geometry/volume.ts` names `foamOffAt` (the bottom's seam into the litres): from then on the figures
 * it would write are the new code's own, and the pin would prove nothing. It ran exactly once. (Nothing in
 * package.json — `--no-install` means npx can only run the tsx already in node_modules. No database is involved.)
 *
 * Each figure is `summarizeDesign(fields).volumeLitres.toPrecision(17)`, a string, so the test compares every
 * digit a double holds.
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { phase16SurfaceBoards } from "@/lib/geometry/__fixtures__/phase16-boards";
import { summarizeDesign } from "@/lib/geometry/design";

const VOLUME = path.resolve(process.cwd(), "lib/geometry/volume.ts");
const OUTPUT = path.resolve(process.cwd(), "lib/geometry/__fixtures__/phase17-litres-pin.json");

function main() {
  if (!existsSync(VOLUME)) {
    throw new Error("Run this from the repository root (lib/geometry/volume.ts not found here).");
  }
  if (readFileSync(VOLUME, "utf8").includes("foamOffAt")) {
    throw new Error("the pin records the litres from before the bottom seam — it is never re-run");
  }
  const litres: Record<string, string> = {};
  for (const board of phase16SurfaceBoards()) {
    litres[board.label] = summarizeDesign(board.fields).volumeLitres.toPrecision(17);
  }
  const provenance =
    "GENERATED by scripts/extract-phase17-litres-pin.ts from the app as it stood before the bottom seam " +
    "(Phase 17, D-20; phase16SurfaceBoards, summarizeDesign, toPrecision(17)) — never hand-edit, never re-run";
  writeFileSync(OUTPUT, `${JSON.stringify({ provenance, litres }, null, 2)}\n`);
  for (const [label, value] of Object.entries(litres)) console.log(`${label}: ${Number(value).toFixed(4)} L`);
  console.log(`wrote ${path.relative(process.cwd(), OUTPUT)} (${Object.keys(litres).length} boards)`);
}

try {
  main();
} catch (error: unknown) {
  console.error(error instanceof Error ? error.message : error);
  process.exitCode = 1;
}
